sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-17: keep vehicle.fuel_card_assigned in sync with fuel_card.assigned_vehicle
    var cardId = current.getUniqueValue();
    var newVehicle = current.getValue('assigned_vehicle');
    var oldVehicle = previous ? previous.getValue('assigned_vehicle') : '';

    if (oldVehicle && oldVehicle != newVehicle) {
        var oldV = new GlideRecord('x_1850693_enterp_0_vehicle');
        if (oldV.get(oldVehicle) && oldV.getValue('fuel_card_assigned') == cardId) {
            oldV.setValue('fuel_card_assigned', '');
            oldV.setWorkflow(false);
            oldV.update();
        }
    }

    if (newVehicle) {
        var newV = new GlideRecord('x_1850693_enterp_0_vehicle');
        if (newV.get(newVehicle) && newV.getValue('fuel_card_assigned') != cardId) {
            newV.setValue('fuel_card_assigned', cardId);
            newV.setWorkflow(false);
            newV.update();
        }
    }
})(current, previous);
